def load_template(name: str) -> str:
    tpl_path = os.path.join(os.path.dirname(__file__), "templates", name)
    with open(tpl_path, "r") as f:
        return f.read()


def render_invoice_template(html: str) -> str:
    """Render the email HTML template by replacing loops and placeholders."""

    # -- 1. Replace {{#each item_rows}} ... {{/each}} --
    item_pattern = re.compile(
        r"<!-- \{\{#each item_rows\}\} -->.*?<!-- \{\{/each\}\} -->", re.DOTALL
    )
    item_match = item_pattern.search(html)
    if item_match:
        loop_content = item_match.group(0)
        single_row = re.search(r"(<tr>.*?</tr>)", loop_content, re.DOTALL)
        if single_row:
            row_template = single_row.group(1)
            rows_html = ""
            for i, item in enumerate(ITEM_ROWS):
                bg = "#ffffff" if i % 2 == 0 else "#fafafa"
                row = row_template
                for key, val in item.items():
                    row = row.replace("{{this." + key + "}}", str(val))
                row = row.replace("{{#if @odd}}", bg if i % 2 != 0 else "")
                row = row.replace("{{else}}", "")
                row = row.replace("{{/if}}", "")
                rows_html += "\n                  " + row
            html = html[:item_match.start()] + rows_html + "\n                  " + html[item_match.end():]

    # -- 2. Replace {{#each terms}} ... {{/each}} --
    term_pattern = re.compile(
        r"<!-- \{\{#each terms\}\} -->.*?<!-- \{\{/each\}\} -->", re.DOTALL
    )
    term_match = term_pattern.search(html)
    if term_match:
        loop_content = term_match.group(0)
        single_row = re.search(r"(<tr>.*?</tr>)", loop_content, re.DOTALL)
        if single_row:
            row_template = single_row.group(1)
            terms_html = ""
            for i, term_text in enumerate(TERMS, 1):
                row = row_template
                row = row.replace("{{this.number}}", str(i))
                row = row.replace("{{this.text}}", term_text)
                terms_html += "\n                  " + row
            html = html[:term_match.start()] + terms_html + "\n                  " + html[term_match.end():]

    # -- 3. Replace all remaining {{variable}} placeholders --
    for key, val in INVOICE_DATA.items():
        html = html.replace("{{" + key + "}}", str(val))

    # -- 4. Clean any remaining Handlebars comments/syntax --
    html = re.sub(r"<!-- \{\{#if \w+\}\} -->", "", html)
    html = re.sub(r"<!-- \{\{/if\}\} -->", "", html)
    html = re.sub(r"<!-- \{\{else\}\} -->", "", html)
    html = re.sub(r"\{\{#if\s+\w+\}\}", "", html)
    html = re.sub(r"\{\{/if\}\}", "", html)
    html = re.sub(r"\{\{else\}\}", "", html)
    html = re.sub(r"\{\{#each\s+\w+\}\}", "", html)
    html = re.sub(r"\{\{/each\}\}", "", html)

    return html


async def generate_real_pdf() -> bytes:
    """Call the Python agent's /invoice/generate-pdf to get the REAL WeasyPrint PDF."""

    # Build the payload that the agent's GeneratePDFRequest expects
    payload = {
        "invoice_number": INVOICE_DATA["invoice_no"],
        "customer_name": INVOICE_DATA["buyer_name"],
        "customer_company": INVOICE_DATA["buyer_name"],
        "customer_address": INVOICE_DATA["buyer_address"],
        "customer_gst": INVOICE_DATA["buyer_gstin"],
        "ship_to_address": INVOICE_DATA["ship_to_address"],
        "mode_of_delivery": "BY TRANSPORT",
        "items": [
            {"description": item["description"], "hsn_code": item["hsn_code"],
             "quantity": int(item["qty"]), "unit_price": float(item["rate"].replace(",", "")),
             "gst_rate": float(item["gst_percent"])}
            for item in ITEM_ROWS
        ],
        "gst_rate": 18.0,
        "invoice_date": "2026-07-25",
        "bank_name": INVOICE_DATA["bank_account_name"],
        "bank_bank": INVOICE_DATA["bank_name"].split(" - ")[0],
        "bank_account_no": INVOICE_DATA["bank_account_no"],
        "bank_ifsc": INVOICE_DATA["bank_ifsc"],
    }

    print(f"\n--- Generating REAL PDF via agent at {AGENT_URL}/invoice/generate-pdf ---")

    try:
        async with httpx.AsyncClient(timeout=60) as client:
            resp = await client.post(
                f"{AGENT_URL}/invoice/generate-pdf",
                json=payload,
                headers={"Content-Type": "application/json"},
            )

            if resp.status_code == 200:
                content_type = resp.headers.get("content-type", "")
                if "application/pdf" in content_type:
                    pdf_bytes = resp.content
                    print(f"  PDF generated: {len(pdf_bytes)} bytes")
                    return pdf_bytes
                else:
                    # Might have returned JSON with file path
                    data = resp.json()
                    print(f"  Agent returned non-PDF: {data}")
                    # Try to read the file if it's a file path
                    if "detail" in data:
                        print(f"  Error: {data['detail']}")
            else:
                print(f"  Agent returned HTTP {resp.status_code}: {resp.text[:500]}")
    except httpx.ConnectError:
        print(f"  ERROR: Cannot connect to agent at {AGENT_URL}")
        print("  Make sure the agent is running: uvicorn app.main:app --reload --port 8000")
    except Exception as e:
        print(f"  ERROR generating PDF: {e}")

    return None


async def send_invoice_email():
    """Send invoice email with real PDF attachment."""

    # Step 1: Generate the REAL PDF from the agent
    pdf_bytes = await generate_real_pdf()

    if pdf_bytes is None:
        print("\n  PDF generation failed. Cannot send email without PDF.")
        return {"success": False, "error": "PDF generation failed"}

    # Step 2: Render the email HTML template
    template = load_template("invoice_email.html")
    rendered_html = render_invoice_template(template)

    print(f"\n--- Template Rendering Check ---")
    print(f"  buyer_name: {'Gupta Enterprises' in rendered_html}")
    print(f"  invoice_no: {'BARK-INV-2026-0042' in rendered_html}")
    print(f"  Items: {'Automatic Die Cutting' in rendered_html}")
    print(f"  Terms: {'Payment is due within 30 days' in rendered_html}")

    # Step 3: Encode PDF as base64 for Brevo API
    pdf_b64 = base64.b64encode(pdf_bytes).decode("utf-8")

    attachments = [
        {
            "filename": f"Invoice_{INVOICE_DATA['invoice_no']}.pdf",
            "content": pdf_b64,
            "contentType": "application/pdf",
        }
    ]

    subject = f"Invoice {INVOICE_DATA['invoice_no']} -- {INVOICE_DATA['company_name']}"
    print(f"\n--- Sending Invoice Email ---")
    print(f"  To: {TO_EMAIL}")
    print(f"  Subject: {subject}")
    print(f"  PDF Size: {len(pdf_bytes):,} bytes (real WeasyPrint PDF)")

    result = await send_email(TO_EMAIL, subject, rendered_html, attachments=attachments)
    return result


async def main():
    print("=" * 60)
    print("  BARK TECHNOLOGY -- Invoice Email (REAL PDF Attachment)")
    print("=" * 60)

    r = await send_invoice_email()
    print(f"\nResult: {r}")


if __name__ == "__main__":
    asyncio.run(main())
